from itertools import combinations, product


def _route(data, exact, minimum):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bits.get(source, 0)
    start = data["start"]
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (used == coupons if exact else used <= coupons)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(minimum, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bits.get(nxt, 0)
                next_state = (nxt, next_mask, next_used)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, next_used))
    return {"arrival": None}


def _build_route(exact, minimum):
    return lambda data: _route(data, exact, minimum)


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    def rounded(numerator, denominator):
        if data["rounding"] == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    version_choices = [
        [-1] + sorted(row["version"] for row in packages[name])
        for name in names
    ]
    best_vector = None
    best_versions = None

    for vector in product(*version_choices):
        selected = dict(zip(names, vector))
        installed = {name for name, version in selected.items() if version != -1}
        if any(name not in installed or not low <= selected[name] <= high
               for name, (low, high) in roots.items()):
            continue
        if any(version in blocked.get(name, []) or
               (name in pins and pins[name] != version)
               for name, version in selected.items() if version != -1):
            continue

        rows = {}
        for name in installed:
            rows[name] = next(row for row in packages[name]
                              if row["version"] == selected[name])
        edges = {name: [] for name in installed}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = selected.get(other, -1)
                if version == -1 or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        visiting, finished = set(), set()
        def acyclic(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not acyclic(other) for other in edges[name]):
                return False
            visiting.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in edges):
            continue

        closure = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in closure:
                continue
            closure.add(name)
            stack.extend(edges[name])
        if closure != installed:
            continue
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = {name: selected[name] for name in names
                             if selected[name] != -1}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    if mandatory & blocked:
        return {"error": "impossible"}
    options = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for chosen in combinations(options, k):
        ids = {job["id"] for job in chosen}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in chosen:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active = []
        valid = True
        for start, end in sorted((job["start"], job["end"]) for job in chosen):
            active = [finish for finish in active if finish > start]
            active.append(end)
            if len(active) > 2:
                valid = False
                break
        if not valid:
            continue

        value = sum(job["value"] for job in chosen)
        id_list = tuple(sorted(ids))
        if (best_value is None or value > best_value or
                (value == best_value and id_list > best_ids)):
            best_value, best_ids = value, id_list

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


